import {useCallback,useEffect,useMemo,useState} from 'react';
import type {FormEvent,ChangeEvent,ReactNode} from 'react';
import {
  Activity,AlertCircle,ArrowDownToLine,ArrowRight,BarChart3,BookOpenText,Building2,
  CalendarDays,CheckCircle2,ChevronDown,ChevronRight,ClipboardList,Clock3,CloudOff,
  Database,FilePlus2,FileText,Filter,FolderKanban,HardDrive,History,KeyRound,
  LayoutDashboard,LogOut,Menu,Pencil,Plus,Printer,RefreshCw,
  Save,Search,Settings2,ShieldCheck,SlidersHorizontal,Trash2,Upload,Users,Wallet,X
} from 'lucide-react';
import QRCode from 'qrcode';
import {ChecklistBoard,RosterCalendar,ProjectRegistry,RecordHistory} from './OperationsBoards';
import type {Account,AuthStatus,Dashboard,ModuleId,RecordItem,Site,UserItem,Role} from './types';
import {labelFor,moduleIds,modules,type Field} from './schema';

type Screen='dashboard'|'cluster'|'sites'|'users'|'permissions'|'audit'|'settings'|'backup'|ModuleId;
const api=<T,>(action:string,payload:Record<string,unknown>={})=>window.lotus.invoke(action,payload) as Promise<T>;
const cn=(...v:(string|boolean|undefined)[])=>v.filter(Boolean).join(' ');
const dateNice=(v:unknown)=>{if(!v)return '—';const d=new Date(String(v));return isNaN(d.getTime())?String(v):d.toLocaleDateString('vi-VN')};
const nfmt=(n:unknown)=>Number(n||0).toLocaleString('vi-VN');
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const firstTitle=(r:RecordItem)=>String(r.data.title||r.data.name||r.data.employee||r.data.account||r.data.assetCode||'Không có tiêu đề');
const statusColor=(v:unknown)=>{
  const s=String(v??'').toLowerCase();
  if(['done','completed','active','approved','purchased','renewed'].includes(s))return 'green';
  if(['critical','high','expired','not done','cancelled','retired'].includes(s))return 'red';
  if(['in progress','pending','planning','deferred','on hold','expiring'].includes(s))return 'orange';
  return 'gray';
};
const menuIcons:Record<string,typeof Activity>={dashboard:LayoutDashboard,cluster:Building2,tasks:Activity,checklists:ClipboardList,roster:CalendarDays,inventory:HardDrive,contracts:FileText,pl:BarChart3,capex:Wallet,projects:FolderKanban,knowledge:BookOpenText,sites:Building2,users:Users,permissions:ShieldCheck,audit:History,settings:Settings2,backup:Database};
const roleNames:Record<Role,string>={SYS:'System Admin',MANAGER:'Manager',SUPERVISOR:'Supervisor',STAFF:'Staff'};
const screenNames:Record<string,string>={dashboard:'Dashboard',cluster:'Cluster Overview',sites:'Sites',users:'Users',permissions:'Permissions',audit:'Audit Log',settings:'Settings',backup:'Backup'};
const schemaGroups:[string,ModuleId[]][]=[['DAILY',['tasks','checklists','roster']],['OPERATIONAL',['inventory','contracts']],['STRATEGIC',['pl','capex','projects']],['RESOURCES',['knowledge']]];
function Icon({name,size=18}:{name:string;size?:number}){const Component=menuIcons[name]||Activity;return <Component size={size} strokeWidth={1.85}/>}
function initials(x:string){return x.split(/\s+/).filter(Boolean).slice(-2).map(w=>w[0].toUpperCase()).join('')||'IT'}

export default function App(){
 const [auth,setAuth]=useState<AuthStatus|null>(null),[screen,setScreen]=useState<Screen>('dashboard'),[siteId,setSiteId]=useState('');
 const [busy,setBusy]=useState(false),[toast,setToast]=useState<{text:string;error?:boolean}|null>(null),[sidebarOpen,setSidebarOpen]=useState(false);
 const [reload,setReload]=useState(0);
 const loadAuth=useCallback(async()=>{try{const state=await api<AuthStatus>('auth.status');setAuth(state);if(state.authenticated){setSiteId(current=>state.sites?.some(s=>s.id===current)?current:state.user?.siteId||state.sites?.[0]?.id||'');}}catch(e){setToast({text:err(e),error:true})}},[]);
 useEffect(()=>{void loadAuth()},[loadAuth]);
 const flash=useCallback((text:string,error=false)=>{setToast({text,error});window.setTimeout(()=>setToast(null),4200)},[]);
 const action=useCallback(async(fn:()=>Promise<unknown>,message?:string)=>{try{setBusy(true);await fn();if(message)flash(message);setReload(v=>v+1)}catch(e){flash(err(e),true)}finally{setBusy(false)}},[flash]);
 async function logout(){await action(async()=>{await api('auth.logout');setAuth({authenticated:false,ready:true});setScreen('dashboard')})}
 if(!auth)return <div className="splash"><div className="spinner"/> Đang khởi tạo Lotus IT Command...</div>;
 if(!auth.authenticated)return <AuthScreen ready={!!auth.ready} onSuccess={loadAuth} notify={flash}/>;
 const site=auth.sites?.find(s=>s.id===siteId)||auth.sites?.[0];
 const user=auth.user!;
 const canAdmin=user.role==='SYS';
 const menuItem=(id:Screen,title:string)=> <button key={id} className={cn('navitem',screen===id&&'active')} onClick={()=>{setScreen(id);setSidebarOpen(false)}}><Icon name={id}/><span>{title}</span>{screen===id&&<span className="navdot"/>}</button>;
 const pageTitle=moduleIds.includes(screen as ModuleId)?modules[screen as ModuleId].title:screenNames[screen]||screen;
 return <div className="app">
  <aside className={cn('sidebar',sidebarOpen&&'mobile-show')}>
    <div className="brand"><div className="brand-icon"><Activity size={22}/></div><div><strong>LOTUS<span> IT</span></strong><small>COMMAND CENTER <b>v0.2</b></small></div></div>
    <div className="sidebar-site">WORKSPACE <span className="offline-pill"><CloudOff size={12}/> Offline</span></div>
    <div className="side-scroll">
      <div className="navgroup"><div className="navlabel">OVERVIEW</div>{menuItem('dashboard','Dashboard')}{canAdmin&&menuItem('cluster','Cluster Overview')}</div>
      {schemaGroups.map(([title,ids])=><div className="navgroup" key={title}><div className="navlabel">{title}</div>{ids.map(id=>menuItem(id,modules[id].title))}</div>)}
      {canAdmin&&<div className="navgroup"><div className="navlabel">SYSTEM ADMIN</div>{menuItem('users','Users')}{menuItem('sites','Sites')}{menuItem('permissions','Permissions')}{menuItem('settings','Settings')}{menuItem('audit','Audit Log')}{menuItem('backup','Backup & Restore')}</div>}
    </div>
    <div className="sidebar-bottom"><div className="usercard"><div className="avatar">{initials(user.name)}</div><div className="usercard-text"><strong>{user.name}</strong><span>{roleNames[user.role]}</span></div><button title="Đăng xuất" onClick={logout} className="iconbtn dark"><LogOut size={17}/></button></div></div>
  </aside>
  {sidebarOpen&&<div className="backdrop mobile-only" onClick={()=>setSidebarOpen(false)}/>}
  <div className="main-shell">
    <header className="topbar"><div className="crumb"><button className="iconbtn mobile-only" onClick={()=>setSidebarOpen(true)}><Menu/></button><span className="crumb-root">Workspace</span><ChevronRight size={14}/><strong>{pageTitle}</strong></div>
      <div className="topbar-right"><span className="app-version">LOCAL DESKTOP</span><div className="select-site"><Building2 size={15}/><select aria-label="Cơ sở hiện tại" value={siteId} onChange={e=>setSiteId(e.target.value)}>{auth.sites?.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><ChevronDown size={14}/></div><button className="iconbtn profile-top" title="Đăng xuất" onClick={logout}><LogOut size={18}/></button></div>
    </header>
    <main className="page">
      {user.forceReset?<ChangePassword onSaved={()=>void loadAuth()} notify={flash}/>:
      !site?<Empty title="Chưa có cơ sở" desc="Vui lòng thêm khách sạn trong phần quản trị."/>:
      screen==='dashboard'?<DashboardScreen key={site.id+reload} site={site} user={user} onNavigate={setScreen} notify={flash}/>:
      screen==='cluster'&&canAdmin?<ClusterScreen sites={auth.sites||[]} onGoto={sid=>{setSiteId(sid);setScreen('dashboard')}}/>:
      moduleIds.includes(screen as ModuleId)?<ModuleScreen key={screen+site.id+reload} module={screen as ModuleId} site={site} user={user} action={action} notify={flash}/>:
      screen==='users'&&canAdmin?<UsersScreen sites={auth.sites||[]} action={action}/>:
      screen==='sites'&&canAdmin?<SitesScreen sites={auth.sites||[]} onRefresh={async()=>{await loadAuth();setReload(v=>v+1)}} action={action}/>:
      screen==='permissions'&&canAdmin?<PermissionsScreen action={action}/>:
      screen==='audit'&&canAdmin?<AuditScreen site={site}/>:
      screen==='settings'&&canAdmin?<SettingsScreen action={action}/>:
      screen==='backup'&&canAdmin?<BackupScreen action={action} onImported={async()=>{setAuth({authenticated:false,ready:true})}}/>:
      <Empty title="Không có quyền truy cập" desc="Bạn không được phép mở màn hình quản trị này."/>}
    </main>
  </div>
  {busy&&<div className="busy-overlay"><div className="spinner"/> Đang lưu dữ liệu...</div>}
  {toast&&<div className={cn('toast',toast.error&&'error')}><span>{toast.error?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}</span>{toast.text}<button className="iconbtn" onClick={()=>setToast(null)}><X size={14}/></button></div>}
 </div>;
}
function err(e:unknown){return e instanceof Error?e.message:String(e)}

function AuthScreen({ready,onSuccess,notify}:{ready:boolean;onSuccess:()=>Promise<void>;notify:(x:string,error?:boolean)=>void}){
 const [form,setForm]=useState({name:'',siteName:'Golden Lotus Grand Hotel',username:'',password:''}),[busy,setBusy]=useState(false);
 const field=(key:keyof typeof form,label:string,type='text')=><label className="field"><span>{label}</span><input autoComplete={key==='password'?'current-password':'off'} type={type} value={form[key]} required onChange={e=>setForm(v=>({...v,[key]:e.target.value}))}/></label>;
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);try{await api(ready?'auth.login':'auth.setup',form);if(!ready){notify('Đã khởi tạo. Đăng nhập bằng tài khoản vừa tạo.');}else await onSuccess();if(!ready)await onSuccess()}catch(e){notify(err(e),true)}finally{setBusy(false)}}
 return <div className="auth-bg"><div className="auth-decoration auth-decoration-a"/><div className="auth-decoration auth-decoration-b"/><div className="auth-card"><div className="auth-mark"><Activity size={27}/></div><div className="auth-sub">LOTUS IT COMMAND</div><h1>{ready?'Chào mừng trở lại':'Thiết lập hệ thống'}</h1><p>{ready?'Đăng nhập để truy cập trung tâm vận hành IT của khách sạn.':'Tạo tài khoản quản trị đầu tiên. Toàn bộ dữ liệu lưu trên máy này.'}</p>
  <form onSubmit={submit}>{!ready&&<>{field('siteName','Tên khách sạn')}{field('name','Họ và tên quản trị')}</>}{field('username','Tên đăng nhập')}{field('password',ready?'Mật khẩu':'Mật khẩu (từ 10 ký tự, gồm chữ và số)','password')}<button className="btn primary wide auth-submit" disabled={busy}>{busy?'Đang xử lý...':ready?'Đăng nhập':'Khởi tạo hệ thống'} <ArrowRight size={16}/></button></form>
  <div className="auth-foot"><ShieldCheck size={15}/> Mã hóa mật khẩu · Cơ sở dữ liệu cục bộ · Không cần Internet</div>
 </div></div>
}
function ChangePassword({onSaved,notify}:{onSaved:()=>void;notify:(x:string,error?:boolean)=>void}){
 const [oldPassword,setOld]=useState(''),[newPassword,setNew]=useState('');
 return <div className="panel small-panel"><h2>Đổi mật khẩu bắt buộc</h2><p className="muted">Quản trị viên yêu cầu bạn đặt lại mật khẩu trước khi sử dụng hệ thống.</p><form onSubmit={async e=>{e.preventDefault();try{await api('auth.changePassword',{oldPassword,newPassword});notify('Đổi mật khẩu thành công.');onSaved()}catch(e){notify(err(e),true)}}}><label className="field">Mật khẩu hiện tại<input type="password" value={oldPassword} onChange={e=>setOld(e.target.value)}/></label><label className="field">Mật khẩu mới (từ 10 ký tự, có chữ và số)<input type="password" value={newPassword} onChange={e=>setNew(e.target.value)}/></label><button className="btn primary">Cập nhật mật khẩu</button></form></div>
}
function PageHead({eyebrow,title,desc,actions}:{eyebrow?:string;title:string;desc?:string;actions?:ReactNode}){
 return <div className="pagehead"><div><div className="eyebrow">{eyebrow||'IT OPERATIONS CENTER'}</div><h1>{title}</h1>{desc&&<p>{desc}</p>}</div><div className="head-actions">{actions}</div></div>;
}
function Kpi({name,value,sub,icon,tone='blue'}:{name:string;value:string|number;sub?:string;icon:ReactNode;tone?:string}){return <div className="kpi"><div className="kpi-heading"><span>{name}</span><div className={cn('kpi-icon',tone)}>{icon}</div></div><strong>{value}</strong><small>{sub}</small></div>}
function Empty({title,desc}:{title:string;desc:string}){return <div className="empty"><div className="empty-icon"><FilePlus2 size={26}/></div><h3>{title}</h3><p>{desc}</p></div>}
function Badge({text}:{text:unknown}){return <span className={cn('status',statusColor(text))}><span className="dot"/>{String(text||'—')}</span>}

function DashboardScreen({site,user,onNavigate,notify}:{site:Site;user:Account;onNavigate:(s:Screen)=>void;notify:(s:string,e?:boolean)=>void}){
 const [stats,setStats]=useState<Dashboard|null>(null);
 useEffect(()=>{api<Dashboard>('dashboard.get',{siteId:site.id}).then(setStats).catch(e=>notify(err(e),true))},[site.id,notify]);
 if(!stats)return <div className="loading-content"><div className="spinner"/> Đang tải Dashboard...</div>;
 const total=Object.values(stats.counts).reduce<number>((v,n)=>v+(n||0),0);
 return <><PageHead eyebrow={`SITE OVERVIEW • ${site.code}`} title={`Xin chào, ${user.name.split(' ').slice(-1)[0]} 👋`} desc={`Tổng quan hoạt động công nghệ thông tin tại ${site.name}.`} actions={<span className="datepill"><CalendarDays size={15}/>{new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'})}</span>}/>
  <div className="section-intro"><span>DAILY OPERATIONS</span><span>HOẠT ĐỘNG HÀNG NGÀY</span></div>
  <div className="kpi-grid"><Kpi name="Công việc đang mở" value={stats.openTasks} sub="Cần xử lý hoặc đang thực hiện" tone="orange" icon={<ClipboardList/>}/><Kpi name="Checklist hoàn thành" value={`${stats.checksDone}/${stats.checkTotal}`} sub="Lượt kiểm tra đã hoàn thành" tone="green" icon={<CheckCircle2/>}/><Kpi name="Hợp đồng gần hết hạn" value={stats.expiringContracts} sub="Trong 30 ngày tới" tone="red" icon={<Clock3/>}/><Kpi name="Bảo hành sắp hết" value={stats.warrantySoon} sub="Trong 30 ngày tới" tone="blue" icon={<HardDrive/>}/></div>
  <div className="section-intro"><span>MANAGEMENT INSIGHTS</span><span>TỔNG HỢP DỮ LIỆU</span></div>
  <div className="dash-row"><div className="panel stat-panel"><div className="panel-header"><div><h3>Tổng quan theo phân hệ</h3><p>Thống kê bản ghi đang quản lý</p></div><div className="mini-counter">{total} bản ghi</div></div>
    <div className="barlist">{moduleIds.filter(m=>stats.counts[m]!==null).map(m=><button className="barlist-row" key={m} onClick={()=>onNavigate(m)}><span>{modules[m].title}</span><div className="bartrack"><div className="barfill" style={{width:`${Math.max(2,100*(stats.counts[m]||0)/Math.max(1,...Object.values(stats.counts).map(x=>x||0)))}%`}}/></div><strong>{stats.counts[m]}</strong></button>)}</div>
  </div><div className="panel actions-panel"><div className="panel-header"><div><h3>Truy cập nhanh</h3><p>Đến các công cụ được dùng nhiều</p></div></div><div className="quick-grid">{(['tasks','checklists','inventory','contracts','projects','knowledge'] as ModuleId[]).map(m=><button key={m} onClick={()=>onNavigate(m)} className="quick-tile"><span className="quick-icon"><Icon name={m} size={20}/></span><span>{modules[m].title}</span><ArrowRight size={15}/></button>)}</div><div className="tip"><ShieldCheck size={18}/><span>Dữ liệu hiện được lưu offline trên máy. Hãy sao lưu định kỳ để tránh mất dữ liệu.</span></div></div></div>
  <div className="panel recent-panel"><div className="panel-header"><div><h3>Hoạt động gần đây</h3><p>Những bản ghi mới được cập nhật</p></div></div>{stats.recent.length?<div className="recent-list">{stats.recent.map(r=><div className="recent-item" key={r.id}><div className="recent-icon"><Icon name={r.module}/></div><div><strong>{firstTitle(r)}</strong><small>{modules[r.module].title}</small></div><span>{dateNice(r.updated_at)}</span></div>)}</div>:<Empty title="Chưa có dữ liệu" desc="Bắt đầu bằng cách tạo công việc hoặc thêm tài sản IT."/>}</div>
 </>;
}
function ClusterScreen({sites,onGoto}:{sites:Site[];onGoto:(id:string)=>void}){
 const [data,setData]=useState<{site:Site;stats:Dashboard}[]>([]);
 useEffect(()=>{Promise.all(sites.map(async site=>({site,stats:await api<Dashboard>('dashboard.get',{siteId:site.id})}))).then(setData).catch(()=>setData([]))},[sites]);
 return <><PageHead title="Cluster Overview" desc="Một góc nhìn tổng hợp cho toàn bộ cơ sở thuộc hệ thống khách sạn."/><div className="cluster-grid">{data.map(({site,stats})=><div key={site.id} className="panel cluster-card"><div className="cluster-top"><div className="cluster-brand"><Building2/><div><strong>{site.name}</strong><span>{site.code} · {site.currency}</span></div></div><button className="iconbtn" onClick={()=>onGoto(site.id)} title="Xem Dashboard"><ArrowRight/></button></div><div className="cluster-stats"><div><span>Tasks</span><strong>{stats.counts.tasks??'—'}</strong></div><div><span>Checklist</span><strong>{stats.counts.checklists??'—'}</strong></div><div><span>Inventory</span><strong>{stats.counts.inventory??'—'}</strong></div><div><span>Contracts</span><strong>{stats.counts.contracts??'—'}</strong></div></div><div className="cluster-alert">{stats.openTasks} công việc đang mở · {stats.expiringContracts} hợp đồng gần hết hạn</div></div>)}</div></>;
}
function ModuleScreen({module,site,user,action,notify}:{module:ModuleId;site:Site;user:Account;action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>;notify:(s:string,e?:boolean)=>void}){
 const spec=modules[module];const [records,setRecords]=useState<RecordItem[]>([]),[loading,setLoading]=useState(true),[term,setTerm]=useState(''),[filter,setFilter]=useState('all'),[period,setPeriod]=useState<'today'|'tomorrow'|'records'>('today'),[selected,setSelected]=useState<string[]>([]),[editing,setEditing]=useState<RecordItem|null|undefined>(undefined),[qrView,setQrView]=useState<{name:string;code:string;src:string}|null>(null),[config,setConfig]=useState<Record<string,any>>({}),[bulkOpen,setBulkOpen]=useState(false);
 const canWrite=user.role==='SYS'||user.role==='MANAGER'||(user.role==='SUPERVISOR'&&['tasks','checklists','roster','inventory','contracts','projects','knowledge'].includes(module))||(user.role==='STAFF'&&['tasks','checklists','roster','knowledge'].includes(module));
 const override=user.overrides?.[module]?.write;const allowWrite=override==='allow'||(override!=='deny'&&canWrite);
 const refresh=useCallback(async()=>{setLoading(true);try{setRecords(await api<RecordItem[]>('records.list',{module,siteId:site.id}))}catch(e){notify(err(e),true)}finally{setLoading(false)}},[module,site.id,notify]);
 useEffect(()=>{void refresh()},[refresh]);
 useEffect(()=>{void api<Record<string,any>>('settings.get').then(setConfig).catch(()=>{})},[]);
 const filtered=useMemo(()=>records.filter(r=>{const matches=JSON.stringify(r.data).toLowerCase().includes(term.toLowerCase());const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const next=`${tomorrow.getFullYear()}-${String(tomorrow.getMonth()+1).padStart(2,'0')}-${String(tomorrow.getDate()).padStart(2,'0')}`;const due=String(r.data.dueDate||'');const periodPass=module!=='tasks'||period==='records'||(period==='today'&&(!due||due<=today()&&r.data.status!=='Done'||due===today()))||(period==='tomorrow'&&due===next);return matches&&periodPass&&(filter==='all'||String(r.data.status||'')===filter)}),[records,term,filter,period,module]);
 const statuses=Array.from(new Set(records.map(r=>String(r.data.status||'')).filter(Boolean)));
 const totalPl=module==='pl'?records.reduce((a,r)=>({budget:a.budget+Number(r.data.budget||0),actual:a.actual+Number(r.data.actual||0)}),{budget:0,actual:0}):null;
 const totalCapex=module==='capex'?records.reduce((n,r)=>n+Number(r.data.quantity||0)*Number(r.data.unitPrice||0),0):null;
 async function exportExcel(){await action(async()=>{const result=await api<{cancelled?:boolean}>('reports.export',{module,siteId:site.id,columns:spec.fields.filter(f=>f.type!=='textarea').map(f=>f.key),labels:Object.fromEntries(spec.fields.map(f=>[f.key,f.label]))});if(!result.cancelled)notify('Đã xuất file Excel thành công.')})}
 async function remove(r:RecordItem){if(!window.confirm(`Xóa ${spec.singular} "${firstTitle(r)}"? Hành động này không thể hoàn tác.`))return;await action(async()=>{await api('records.delete',{module,siteId:site.id,id:r.id});await refresh()},'Đã xóa bản ghi.')}
 async function save(form:Record<string,string|number|boolean|undefined>){await action(async()=>{await api('records.save',{module,siteId:site.id,record:{id:editing?.id,data:form}});setEditing(undefined);await refresh()},'Đã lưu dữ liệu thành công.')}
 async function qrRecord(r:RecordItem){const code=String(r.data.assetCode||r.id);const src=await QRCode.toDataURL(JSON.stringify({app:'Lotus IT Command',siteCode:site.code,assetCode:code}),{width:240,margin:2});setQrView({code,name:firstTitle(r),src})}
 async function printQrs(){await action(async()=>{await api('qr.print',{siteId:site.id,ids:selected});setSelected([])},'Đã mở cửa sổ tem QR. Nhấn Ctrl+P để in.')}
 function displayCell(r:RecordItem,key:string){const v=r.data[key];if(key==='status'||key==='priority')return <Badge text={v}/>;if(key.toLowerCase().includes('date')||key==='checkedAt'||key==='warrantyUntil'||key==='updatedAt')return dateNice(v);if(['budget','actual','unitPrice','purchasePrice','amount'].includes(key))return nfmt(v);return String(v??'—')||'—'}
 return <><PageHead eyebrow={`${spec.group.toUpperCase()} • ${site.code}`} title={spec.title} desc={spec.description} actions={<><button className="btn light" onClick={exportExcel}><ArrowDownToLine size={16}/> Xuất Excel</button>{module==='roster'&&allowWrite&&<button className="btn light" onClick={()=>setBulkOpen(true)}><CalendarDays size={16}/> Gán nhiều ngày</button>}{allowWrite&&<button className="btn primary" onClick={()=>setEditing(null)}><Plus size={17}/> Thêm {spec.singular}</button>}</>}/>
  <div className="kpi-grid compact"><Kpi name="Tổng bản ghi" value={records.length} sub={spec.title} tone="blue" icon={<Icon name={module}/>}/><Kpi name="Cập nhật hôm nay" value={records.filter(x=>x.updated_at.slice(0,10)===today()).length} sub="Thay đổi trong ngày" tone="green" icon={<CheckCircle2/>}/>{module==='pl'?<><Kpi name="Budget" value={nfmt(totalPl?.budget)} icon={<Wallet/>} sub={site.currency}/><Kpi name="Actual" value={nfmt(totalPl?.actual)} icon={<BarChart3/>} sub={`Variance: ${nfmt((totalPl?.actual||0)-(totalPl?.budget||0))}`}/></>:module==='capex'?<><Kpi name="Tổng dự toán" value={nfmt(totalCapex)} icon={<Wallet/>} sub={site.currency}/><Kpi name="Hạng mục hoãn" value={records.filter(r=>r.data.status==='Deferred').length} icon={<Clock3/>} sub="Deferred"/></>:<><Kpi name="Cần chú ý" value={records.filter(r=>['Open','Not Done','Expired','Critical','On Hold'].includes(String(r.data.status))).length} sub="Chưa hoàn tất / có rủi ro" tone="orange" icon={<AlertCircle/>}/><Kpi name="Hoàn tất" value={records.filter(r=>['Done','Completed','Approved'].includes(String(r.data.status))).length} sub="Đã hoàn thành" tone="green" icon={<CheckCircle2/>}/></>}</div>
  {module==='checklists'&&<ChecklistBoard site={site} records={records} config={config} editable={allowWrite} mutate={action} refresh={refresh}/>}
  {module==='roster'&&<RosterCalendar site={site} records={records} config={config} editable={allowWrite} mutate={action} refresh={refresh}/>}
  {module==='projects'&&<ProjectRegistry site={site} records={records} editable={allowWrite} mutate={action} refresh={refresh}/>}
  {module==='capex'&&<Forecast records={records} currency={site.currency}/>}
  <div className="panel data-panel">{module==='tasks'&&<div className="period-tabs">{([['today','Today'],['tomorrow','Tomorrow'],['records','Records']] as const).map(([v,label])=><button key={v} className={cn(period===v&&'active')} onClick={()=>setPeriod(v)}>{label}</button>)}</div>}<div className="list-toolbar"><div className="searchbox"><Search size={18}/><input value={term} onChange={e=>setTerm(e.target.value)} placeholder={`Tìm ${spec.singular}, từ khóa, mã...`}/></div><div className="list-filters">{module==='inventory'&&selected.length>0&&<button className="btn light" onClick={printQrs}><Printer size={15}/> In {selected.length} tem QR</button>}{statuses.length>0&&<div className="select-wrapper"><Filter size={15}/><select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">Tất cả trạng thái</option>{statuses.map(s=><option key={s} value={s}>{s}</option>)}</select></div>}<button className="iconbtn refresh" title="Làm mới" onClick={refresh}><RefreshCw size={17}/></button></div></div>
    {loading?<div className="loading-content"><div className="spinner"/> Đang tải dữ liệu...</div>:filtered.length===0?<Empty title={term?'Không tìm thấy dữ liệu':'Chưa có bản ghi nào'} desc={term?'Thử tìm kiếm bằng từ khóa khác.':`Tạo ${spec.singular} đầu tiên để bắt đầu quản lý.`}/>:<div className="table-scroll"><table className="data-table"><thead><tr>{module==='inventory'&&<th className="check-col"><input type="checkbox" checked={filtered.length>0&&filtered.every(r=>selected.includes(r.id))} onChange={e=>setSelected(e.target.checked?filtered.map(r=>r.id):[])}/></th>}<th className="num-col">#</th>{spec.columns.map(key=><th key={key}>{labelFor(module,key)}</th>)}<th className="action-col">Thao tác</th></tr></thead><tbody>{filtered.map((r,i)=><tr key={r.id}>{module==='inventory'&&<td><input type="checkbox" checked={selected.includes(r.id)} onChange={e=>setSelected(s=>e.target.checked?[...s,r.id]:s.filter(x=>x!==r.id))}/></td>}<td className="muted num-col">{i+1}</td>{spec.columns.map((key,j)=><td key={key}>{j===0?<strong className="cell-title">{displayCell(r,key)}</strong>:module==='tasks'&&key==='status'&&allowWrite?<select className="inline-status" value={String(r.data.status||'Open')} onChange={e=>void action(async()=>{await api('records.save',{module,siteId:site.id,record:{id:r.id,data:{...r.data,status:e.target.value}}});await refresh()},'Đã cập nhật trạng thái.')}><option>Open</option><option>In Progress</option><option>Done</option></select>:displayCell(r,key)}</td>)}<td className="cell-actions"><button className="iconbtn" title="Xem lịch sử thay đổi" onClick={()=>setHistoryRecord(r)}><History size={15}/></button>{module==='inventory'&&<button className="iconbtn" title="Mã QR" onClick={()=>void qrRecord(r)}><Printer size={15}/></button>}{allowWrite&&<><button className="iconbtn" title="Sửa" onClick={()=>setEditing(r)}><Pencil size={15}/></button><button className="iconbtn danger" title="Xóa" onClick={()=>void remove(r)}><Trash2 size={15}/></button></>}</td></tr>)}</tbody></table></div>}
    <div className="list-foot">Đang hiển thị <strong>{filtered.length}</strong> / {records.length} bản ghi <span>· {site.name}</span></div>
  </div>
  {editing!==undefined&&<RecordForm key={editing?.id||'new'} module={module} config={config} data={editing?.data||{}} onClose={()=>setEditing(undefined)} onSave={save} notify={notify}/>}
  {historyRecord&&<RecordHistory site={site} module={module} record={historyRecord} notify={notify} onClose={()=>setHistoryRecord(null)}/>}
  {bulkOpen&&<BulkRoster config={config} onClose={()=>setBulkOpen(false)} onSave={async data=>{await action(async()=>{if(!data.length)throw new Error('Chưa chọn ngày.');await api('roster.batch',{siteId:site.id,employee:data[0].employee,dates:data.map(d=>d.date),shift:data[0].shift,note:data[0].note});setBulkOpen(false);await refresh()},'Đã gán ca hàng loạt.')}}/>}
  {qrView&&<div className="modal-shade" onMouseDown={()=>setQrView(null)}><div className="modal qr-modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><strong>Tem QR thiết bị</strong><button className="iconbtn" onClick={()=>setQrView(null)}><X/></button></div><div className="qr-content"><img src={qrView.src} alt="Mã QR thiết bị"/><h3>{qrView.code}</h3><p>{qrView.name}</p><small>Mã QR chứa mã thiết bị để tra cứu offline. Chưa hỗ trợ liên kết đọc dữ liệu từ điện thoại.</small></div><div className="modal-footer"><button className="btn primary" onClick={async()=>{const r=records.find(x=>String(x.data.assetCode||x.id)===qrView.code);if(r)await api('qr.print',{siteId:site.id,ids:[r.id]})}}><Printer size={17}/> Mở tem để in</button></div></div></div>}
 </>;
}
function Forecast({records,currency}:{records:RecordItem[];currency:string}){
 const start=new Date().getFullYear();const values=Array.from({length:10},(_,i)=>({year:start+i,value:records.reduce((sum,r)=>{const y=Number(r.data.year),cycle=Number(r.data.lifecycleYears),cost=Number(r.data.quantity)*Number(r.data.unitPrice);if(!y||!cycle||cycle<=0||!Number.isFinite(cost)||r.data.status==='Cancelled'||r.data.status==='Deferred')return sum;return start+i>y&&(start+i-y)%cycle===0?sum+cost:sum},0)}));
 const max=Math.max(1,...values.map(x=>x.value));return <div className="panel forecast"><div className="panel-header"><div><h3>10-Year Replacement Forecast</h3><p>Ước tính thay thế thiết bị theo vòng đời • {currency}</p></div></div><div className="forecast-bars">{values.map(x=><div key={x.year} className="forecast-col" title={`${x.year}: ${nfmt(x.value)} ${currency}`}><span className="forecast-value">{x.value?nfmt(x.value):'—'}</span><div className="forecast-bar-bg"><div style={{height:`${Math.max(3,x.value/max*100)}%`}}/></div><small>{x.year}</small></div>)}</div><div className="forecast-note">* Dự báo giả định thay thế theo chu kỳ cố định, chưa tính lạm phát hay chiết khấu.</div></div>
}
function RecordForm({module,config,data,onClose,onSave,notify}:{module:ModuleId;config:Record<string,any>;data:Record<string,string|number|boolean|undefined>;onClose:()=>void;onSave:(form:Record<string,string|number|boolean|undefined>)=>Promise<void>;notify:(s:string,e?:boolean)=>void}){
 const spec=modules[module];const [form,setForm]=useState<Record<string,string|number|boolean|undefined>>(()=>({...data})),[saving,setSaving]=useState(false);
 const set=(k:string,v:string|number|boolean)=>setForm(prev=>({...prev,[k]:v,...(module==='roster'&&k==='shift'?{factor:Number(config.shiftTypes?.find((x:{code:string})=>x.code===v)?.factor??1)}:{})}));
 const fields=spec.fields.map(f=>{if(module==='roster'&&f.key==='shift'&&config.shiftTypes?.length)return {...f,options:config.shiftTypes.map((x:{code:string})=>x.code)};if(module==='checklists'&&f.key==='category'&&config.categories?.length)return{...f,options:config.categories};return f;});
 async function pickFile(){try{const r=await api<{filename:string;originalName:string}|null>('file.pick');if(r){const key=module==='checklists'?'evidence':module==='knowledge'?'attachment':'file';setForm(v=>({...v,[key]:r.originalName,_attachmentName:r.filename}));notify('Đã thêm tệp đính kèm.')}}catch(e){notify(err(e),true)}}
 async function openFile(){if(form._attachmentName){try{await api('file.open',{filename:form._attachmentName})}catch(e){notify(err(e),true)}}}
 async function submit(e:FormEvent){e.preventDefault();if(module==='checklists'&&form.status==='Not Done'&&!String(form.reason||'').trim()){notify('Cần nhập lý do khi kiểm tra Not Done.',true);return}setSaving(true);try{await onSave(form)}finally{setSaving(false)}}
 return <div className="modal-shade" onMouseDown={onClose}><div className="drawer" onMouseDown={e=>e.stopPropagation()}><form onSubmit={submit} className="drawer-form"><div className="drawer-head"><div><div className="eyebrow">{spec.title.toUpperCase()}</div><h2>{Object.keys(data).length?'Chỉnh sửa':'Thêm'} {spec.singular}</h2></div><button type="button" onClick={onClose} className="iconbtn"><X/></button></div><div className="drawer-body">{module==='checklists'&&config.checklistTemplates?.length>0&&<label className="field"><span>Điền nhanh từ mẫu kiểm tra</span><select defaultValue="" onChange={e=>{const x=config.checklistTemplates[Number(e.target.value)];if(x)setForm(v=>({...v,title:x.name,frequency:x.frequency}))}}><option value="">— Chọn mẫu —</option>{config.checklistTemplates.map((t:{name:string},i:number)=><option key={i} value={i}>{t.name}</option>)}</select></label>}<div className="form-grid">{fields.map(f=><FormField key={f.key} field={f} value={form[f.key]} onChange={v=>set(f.key,v)}/>)}</div>{['checklists','inventory','contracts','knowledge','projects'].includes(module)&&<div className="attachment-box"><div><FileText size={18}/><span>{form._attachmentName?'Đã có tệp đính kèm':'Có thể thêm tệp minh chứng / tài liệu (tối đa 10 MB)'}</span></div><div className="attachment-actions">{!!form._attachmentName&&<button type="button" className="btn light" onClick={openFile}>Mở tệp</button>}<button type="button" className="btn light" onClick={pickFile}><Upload size={15}/> Chọn tệp</button></div></div>}{module==='capex'&&<div className="form-hint"><strong>Tổng chi phí dự toán:</strong> {nfmt(Number(form.quantity||0)*Number(form.unitPrice||0))}</div>}{module==='pl'&&<div className="form-hint"><strong>Variance (Actual - Budget):</strong> {nfmt(Number(form.actual||0)-Number(form.budget||0))}</div>}</div><div className="drawer-footer"><button type="button" className="btn light" onClick={onClose}>Hủy</button><button disabled={saving} className="btn primary"><Save size={16}/>{saving?'Đang lưu...':'Lưu thông tin'}</button></div></form></div></div>
}
function FormField({field,value,onChange}:{field:Field;value:string|number|boolean|undefined;onChange:(v:string|number)=>void}){
 const props={id:field.key,value:value===undefined||value===null?'':String(value),required:field.required,onChange:(e:ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>onChange(field.type==='number'&&e.target.value!==''?Number(e.target.value):e.target.value)};
 return <label className={cn('field',field.wide&&'span-2')}><span>{field.label}{field.required&&<em>*</em>}</span>{field.type==='textarea'?<textarea {...props} rows={4} placeholder={field.placeholder||'Nhập thông tin...'} />:field.type==='select'?<select {...props}><option value="">— Chọn —</option>{field.options?.map(o=><option key={o} value={o}>{o}</option>)}</select>:<input type={field.type==='number'?'number':field.type==='date'?'date':field.type==='month'?'month':'text'} step={field.type==='number'?'any':undefined} placeholder={field.placeholder||''} {...props}/>}</label>
}
function SitesScreen({sites,onRefresh,action}:{sites:Site[];onRefresh:()=>Promise<void>;action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>}){
 const [editing,setEditing]=useState<Partial<Site>|null>(null);
 return <><PageHead title="Sites" desc="Quản lý khách sạn và các cơ sở trong cụm. Mỗi cơ sở có dữ liệu độc lập theo site ID." actions={<button className="btn primary" onClick={()=>setEditing({code:'',name:'',currency:'VND'})}><Plus size={17}/> Thêm cơ sở</button>}/><div className="sites-grid">{sites.map(s=><div className="panel site-card" key={s.id}><div className="site-symbol"><Building2 size={22}/></div><div className="site-head"><h3>{s.name}</h3><span className="status green"><span className="dot"/>Active</span></div><p>Mã cơ sở: <strong>{s.code}</strong></p><p>Tiền tệ: <strong>{s.currency}</strong></p><button className="btn light" onClick={()=>setEditing(s)}><Pencil size={15}/> Chỉnh sửa cơ sở</button></div>)}</div>
  {editing&&<div className="modal-shade" onMouseDown={()=>setEditing(null)}><div className="modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><h3>{editing.id?'Chỉnh sửa':'Thêm'} cơ sở</h3><button className="iconbtn" onClick={()=>setEditing(null)}><X/></button></div><form onSubmit={async e=>{e.preventDefault();await action(async()=>{await api('sites.save',editing as Record<string,unknown>);setEditing(null);await onRefresh()},'Đã lưu cơ sở thành công.')}}><div className="modal-body">{(['code','name','currency'] as const).map(k=><label className="field" key={k}><span>{k==='code'?'Mã cơ sở':k==='name'?'Tên khách sạn':'Tiền tệ'}</span><input required value={editing[k]||''} onChange={e=>setEditing({...editing,[k]:e.target.value})}/></label>)}</div><div className="modal-footer"><button type="button" className="btn light" onClick={()=>setEditing(null)}>Hủy</button><button className="btn primary"><Save size={16}/> Lưu</button></div></form></div></div>}
 </>;
}
function UsersScreen({sites,action}:{sites:Site[];action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>}){
 const [users,setUsers]=useState<UserItem[]>([]),[editing,setEditing]=useState<Record<string,any>|null>(null);
 const load=useCallback(async()=>setUsers(await api<UserItem[]>('users.list')),[]);
 useEffect(()=>{void load()},[load]);
 const start=(user?:UserItem)=>setEditing(user?{...user,overrides:JSON.parse(user.overrides||'{}')}:{username:'',full_name:'',role:'STAFF',password:'',siteIds:sites.length?[sites[0].id]:[],active:1,force_reset:1,overrides:{}});
 return <><PageHead title="User Management" desc="Tạo tài khoản và giới hạn phạm vi truy cập theo vai trò, khách sạn." actions={<button className="btn primary" onClick={()=>start()}><Plus size={16}/> Thêm nhân sự</button>}/><div className="panel data-panel"><div className="table-scroll"><table className="data-table"><thead><tr><th>Nhân sự</th><th>Tên đăng nhập</th><th>Vai trò</th><th>Cơ sở được truy cập</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><div className="person-cell"><span className="avatar small">{initials(u.full_name)}</span><strong>{u.full_name}</strong></div></td><td>{u.username}</td><td><Badge text={u.role}/></td><td>{sites.filter(s=>u.siteIds.includes(s.id)).map(s=>s.code).join(', ')}</td><td><Badge text={u.active?'Active':'Disabled'}/></td><td><button className="iconbtn" onClick={()=>start(u)}><Pencil size={16}/></button></td></tr>)}</tbody></table></div></div>
  {editing&&<div className="modal-shade" onMouseDown={()=>setEditing(null)}><div className="drawer" onMouseDown={e=>e.stopPropagation()}><form className="drawer-form" onSubmit={async e=>{e.preventDefault();await action(async()=>{await api('users.save',editing);setEditing(null);await load()},'Đã lưu tài khoản.')}}><div className="drawer-head"><div><div className="eyebrow">USER PROFILE</div><h2>{editing.id?'Chỉnh sửa nhân sự':'Thêm nhân sự'}</h2></div><button className="iconbtn" type="button" onClick={()=>setEditing(null)}><X/></button></div><div className="drawer-body"><div className="form-grid">{[['full_name','Họ và tên'],['username','Tên đăng nhập']] .map(([key,label])=><label key={key} className="field"><span>{label}</span><input required value={editing[key]||''} onChange={e=>setEditing({...editing,[key]:e.target.value})}/></label>)}{!editing.id&&<label className="field span-2"><span>Mật khẩu ban đầu (ít nhất 10 ký tự, chữ và số)</span><input type="password" required value={editing.password||''} onChange={e=>setEditing({...editing,password:e.target.value})}/></label>}<label className="field"><span>Vai trò</span><select value={editing.role} onChange={e=>setEditing({...editing,role:e.target.value})}>{(['SYS','MANAGER','SUPERVISOR','STAFF'] as Role[]).map(r=><option key={r}>{r}</option>)}</select></label><label className="field"><span>Quản lý trực tiếp</span><select value={editing.report_to||''} onChange={e=>setEditing({...editing,report_to:e.target.value})}><option value="">Không có</option>{users.filter(u=>u.id!==editing.id).map(u=><option value={u.id} key={u.id}>{u.full_name}</option>)}</select></label></div><div className="field"><span>Cơ sở được truy cập</span><div className="check-panel">{sites.map(s=><label className="checkbox-line" key={s.id}><input type="checkbox" checked={(editing.siteIds||[]).includes(s.id)} onChange={e=>setEditing({...editing,siteIds:e.target.checked?[...editing.siteIds,s.id]:editing.siteIds.filter((x:string)=>x!==s.id)})}/>{s.name}</label>)}</div></div><div className="check-panel"><label className="checkbox-line"><input type="checkbox" checked={!!editing.active} onChange={e=>setEditing({...editing,active:e.target.checked?1:0})}/> Tài khoản được phép đăng nhập</label><label className="checkbox-line"><input type="checkbox" checked={!!editing.force_reset} onChange={e=>setEditing({...editing,force_reset:e.target.checked?1:0})}/> Bắt buộc thay đổi mật khẩu</label></div><div className="field"><span>Quyền ghi đè riêng từng phân hệ (Override)</span><div className="override-list">{moduleIds.map(m=><div className="override-line" key={m}><span>{modules[m].title}</span>{(['read','write'] as const).map(mode=><label key={mode}>{mode==='read'?'Xem':'Sửa'}<select value={editing.overrides?.[m]?.[mode]||'default'} onChange={e=>setEditing((prev:any)=>({...prev,overrides:{...prev.overrides,[m]:{...prev.overrides?.[m],[mode]:e.target.value}}}))}><option value="default">Theo vai trò</option><option value="allow">Allow</option><option value="deny">Deny</option></select></label>)}</div>)}</div></div>{editing.id&&<button type="button" className="btn light" onClick={async()=>{const password=window.prompt('Nhập mật khẩu mới (từ 10 ký tự, gồm chữ và số):');if(password)await action(async()=>api('users.password',{userId:editing.id,password}),'Đã đặt lại mật khẩu, người dùng phải đổi khi đăng nhập.')}}><KeyRound size={16}/> Đặt lại mật khẩu</button>}</div><div className="drawer-footer"><button type="button" className="btn light" onClick={()=>setEditing(null)}>Hủy</button><button className="btn primary"><Save size={16}/> Lưu thông tin</button></div></form></div></div>}
 </>;
}
function PermissionsScreen({action}:{action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>}){
 type Perm={role:Role;module:ModuleId;can_read:number;can_write:number};
 const [rows,setRows]=useState<Perm[]>([]);const load=useCallback(async()=>{const x=await api<{rows:Perm[]}>('permissions.get');setRows(x.rows)},[]);
 useEffect(()=>{void load()},[load]);
 function toggle(role:Role,module:ModuleId,key:'can_read'|'can_write',yes:boolean){setRows(v=>v.map(x=>x.role===role&&x.module===module?{...x,[key]:yes?1:0,...(key==='can_write'&&yes?{can_read:1}:{})}:x))}
 return <><PageHead title="Permission Matrix" desc="Cấp quyền đọc và chỉnh sửa cho từng vai trò trên mỗi phân hệ. Override của người dùng có mức ưu tiên cao hơn." actions={<button className="btn primary" onClick={()=>void action(async()=>{await api('permissions.save',{rows});await load()},'Đã cập nhật ma trận phân quyền.')}><Save size={16}/> Lưu phân quyền</button>}/><div className="panel data-panel"><div className="table-scroll"><table className="data-table permissions-table"><thead><tr><th rowSpan={2}>Phân hệ</th>{(['MANAGER','SUPERVISOR','STAFF'] as Role[]).map(r=><th key={r} colSpan={2}>{roleNames[r]}</th>)}</tr><tr>{(['MANAGER','SUPERVISOR','STAFF'] as Role[]).flatMap(r=>[<th key={r+'r'}>Xem</th>,<th key={r+'w'}>Sửa</th>])}</tr></thead><tbody>{moduleIds.map(m=><tr key={m}><td className="cell-title">{modules[m].title}</td>{(['MANAGER','SUPERVISOR','STAFF'] as Role[]).flatMap(r=>{const x=rows.find(p=>p.role===r&&p.module===m);return [<td key={r+'r'}><input type="checkbox" checked={!!x?.can_read} onChange={e=>toggle(r,m,'can_read',e.target.checked)}/></td>,<td key={r+'w'}><input type="checkbox" checked={!!x?.can_write} onChange={e=>toggle(r,m,'can_write',e.target.checked)}/></td>]})}</tr>)}</tbody></table></div><div className="list-foot">System Admin luôn có đầy đủ quyền. Kiểm tra quyền được thực hiện tại tiến trình Electron, không chỉ trên giao diện.</div></div></>;
}
function AuditScreen({site}:{site:Site}){
 const [items,setItems]=useState<Array<{id:string;username:string;action:string;details:string;created_at:string;site_id:string}>>([]);
 useEffect(()=>{void api<typeof items>('audit.list',{siteId:site.id}).then(setItems)},[site.id]);
 return <><PageHead title="Audit Log" desc="Nhật ký hoạt động quản trị, truy cập và cập nhật dữ liệu. Giới hạn 500 sự kiện gần nhất."/><div className="panel data-panel"><div className="table-scroll"><table className="data-table"><thead><tr><th>Thời gian</th><th>Người thực hiện</th><th>Hành động</th><th>Chi tiết</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td>{new Date(x.created_at).toLocaleString('vi-VN')}</td><td>{x.username||'System'}</td><td><Badge text={x.action}/></td><td className="mono small-text">{x.details}</td></tr>)}</tbody></table></div></div></>;
}
function SettingsScreen({action}:{action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>}){
 const [categories,setCategories]=useState(''),[shift,setShift]=useState(''),[templates,setTemplates]=useState('');
 const load=useCallback(async()=>{const x=await api<Record<string,any>>('settings.get');setCategories((x.categories||['PMS','POS','Server','NAS','Network','Backup','Printer']).join('\n'));setShift((x.shiftTypes||[{code:'D',factor:1},{code:'N',factor:1},{code:'HD',factor:0.5},{code:'AL',factor:1},{code:'DO',factor:0}]).map((v:{code:string;factor:number})=>`${v.code}|${v.factor}`).join('\n'));setTemplates((x.checklistTemplates||[{name:'Kiểm tra Backup',frequency:'Daily'},{name:'Kiểm tra NAS / Server',frequency:'Daily'}]).map((v:{name:string;frequency:string})=>`${v.name}|${v.frequency}`).join('\n'))},[]);
 useEffect(()=>{void load()},[load]);
 async function save(){await action(async()=>{const shiftTypes=shift.split('\n').map(x=>x.split('|')).filter(x=>x.length===2).map(([code,factor])=>({code:code.trim(),factor:Number(factor)}));const checklistTemplates=templates.split('\n').map(x=>x.split('|')).filter(x=>x.length===2).map(([name,frequency])=>({name:name.trim(),frequency:frequency.trim()}));await api('settings.save',{key:'categories',value:categories.split('\n').map(x=>x.trim()).filter(Boolean)});await api('settings.save',{key:'shiftTypes',value:shiftTypes});await api('settings.save',{key:'checklistTemplates',value:checklistTemplates});await load()},'Đã lưu cấu hình hệ thống.')}
 return <><PageHead title="System Settings" desc="Thiết lập danh mục sử dụng chung, mã ca làm việc và mẫu kiểm tra." actions={<button className="btn primary" onClick={save}><Save size={16}/> Lưu cấu hình</button>}/><div className="settings-grid"><div className="panel settings-card"><div className="settings-icon"><SlidersHorizontal/></div><h3>Danh mục hệ thống</h3><p>Mỗi dòng một danh mục. Có thể sử dụng làm danh sách tham chiếu khi mở rộng phần mềm.</p><textarea value={categories} onChange={e=>setCategories(e.target.value)} rows={10}/></div><div className="panel settings-card"><div className="settings-icon"><CalendarDays/></div><h3>Mã ca làm việc</h3><p>Định dạng Mã ca | Hệ số công (ví dụ: HD|0.5). Các mã ca đang có trong màn Roster là mặc định.</p><textarea value={shift} onChange={e=>setShift(e.target.value)} rows={10}/></div><div className="panel settings-card"><div className="settings-icon"><ClipboardList/></div><h3>Mẫu Checklist</h3><p>Định dạng Tên mẫu | Chu kỳ (Daily / Weekly / Monthly / Quarterly / Semiannual / Yearly / Custom). Các mẫu sẽ hiện tự động theo kỳ trên bảng Checklist.</p><textarea value={templates} onChange={e=>setTemplates(e.target.value)} rows={10}/></div><div className="panel settings-card"><div className="settings-icon"><ShieldCheck/></div><h3>Thiết lập dữ liệu</h3><p>Giới hạn tệp đính kèm: 10 MB. Cho phép ảnh, PDF, Word, Excel, TXT, WEBP.</p><div className="config-line"><span>Database engine</span><strong>SQLite (sql.js)</strong></div><div className="config-line"><span>Storage</span><strong>Offline / Local</strong></div><div className="config-line"><span>Security</span><strong>scrypt password hash</strong></div><div className="config-line"><span>Tài khoản quản trị</span><strong>Role-based</strong></div></div></div></>;
}
function BackupScreen({action,onImported}:{action:(fn:()=>Promise<unknown>,msg?:string)=>Promise<void>;onImported:()=>Promise<void>}){
 return <><PageHead title="Backup & Restore" desc="Sao lưu hoặc phục hồi dữ liệu SQLite. Khuyến nghị lưu bản sao ở ổ cứng ngoài hoặc thư mục được OneDrive đồng bộ."/><div className="backup-grid"><div className="panel backup-card"><div className="backup-icon blue"><ArrowDownToLine size={26}/></div><h2>Sao lưu toàn bộ</h2><p>Xuất bản sao cơ sở dữ liệu hiện tại ra file .db, bao gồm tài khoản, cơ sở, lịch sử và bản ghi. Tệp đính kèm nằm trong thư mục attachments riêng và chưa nằm trong bản sao này.</p><button className="btn primary" onClick={()=>void action(async()=>{await api('backup.export')},'Đã xử lý yêu cầu sao lưu.')}><ArrowDownToLine size={17}/> Sao lưu dữ liệu</button></div><div className="panel backup-card"><div className="backup-icon orange"><Upload size={26}/></div><h2>Khôi phục dữ liệu</h2><p>Nhập lại file .db đã sao lưu. Hệ thống tự tạo bản .bak của cơ sở dữ liệu trước khi thay thế. Bạn cần đăng nhập lại sau khi khôi phục.</p><button className="btn light" onClick={async()=>{if(window.confirm('Khôi phục sẽ thay thế toàn bộ dữ liệu hiện tại. Bạn đã sao lưu chưa?'))await action(async()=>{const r=await api<{cancelled?:boolean}>('backup.import');if(!r.cancelled)await onImported()},'Hoàn tất khôi phục. Vui lòng đăng nhập lại.')}}><Database size={17}/> Chọn bản sao để khôi phục</button></div></div><div className="warn-strip"><AlertCircle size={20}/> <span><strong>Quan trọng:</strong> Bản sao .db chưa bao gồm các tệp đính kèm. Trước khi chuyển máy, hãy sao lưu thêm thư mục attachments trong AppData của ứng dụng. Không lưu mật khẩu hoặc file backup lên GitHub.</span></div></>;
}
function BulkRoster({config,onClose,onSave}:{config:Record<string,any>;onClose:()=>void;onSave:(records:Record<string,string|number>[])=>Promise<void>}){
 const shifts:{code:string;factor:number}[]=config.shiftTypes||[{code:'D',factor:1},{code:'N',factor:1},{code:'HD',factor:.5},{code:'AL',factor:1},{code:'DO',factor:0}];
 const [form,setForm]=useState({employee:'',start:today(),end:today(),shift:'D',note:''});
 const [error,setError]=useState('');
 async function submit(e:FormEvent){e.preventDefault();const start=new Date(form.start+'T12:00:00'),end=new Date(form.end+'T12:00:00');const days=Math.floor((end.getTime()-start.getTime())/86400000)+1;if(!Number.isFinite(days)||days<1||days>62){setError('Chọn từ 1 đến 62 ngày liên tiếp.');return}const factor=shifts.find(x=>x.code===form.shift)?.factor??1;const records=Array.from({length:days},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return{employee:form.employee,date:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,shift:form.shift,factor,note:form.note}});await onSave(records)}
 return <div className="modal-shade" onMouseDown={onClose}><div className="modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><h3>Gán ca hàng loạt</h3><button className="iconbtn" onClick={onClose}><X/></button></div><form onSubmit={submit}><div className="modal-body"><p className="muted">Chọn khoảng ngày liên tiếp. Mỗi ngày sẽ được lưu thành một bản ghi lịch trực.</p>{[['employee','Nhân viên'],['start','Từ ngày'],['end','Đến ngày']] .map(([k,l])=><label className="field" key={k}><span>{l}</span><input required type={k==='employee'?'text':'date'} value={form[k as 'employee'|'start'|'end']} onChange={e=>setForm(v=>({...v,[k]:e.target.value}))}/></label>)}<label className="field"><span>Ca làm</span><select value={form.shift} onChange={e=>setForm(v=>({...v,shift:e.target.value}))}>{shifts.map(x=><option key={x.code} value={x.code}>{x.code} — hệ số {x.factor}</option>)}</select></label><label className="field"><span>Ghi chú</span><input value={form.note} onChange={e=>setForm(v=>({...v,note:e.target.value}))}/></label>{error&&<p className="input-error">{error}</p>}</div><div className="modal-footer"><button className="btn light" type="button" onClick={onClose}>Hủy</button><button className="btn primary"><Save size={16}/> Lưu lịch trực</button></div></form></div></div>
}